string MaskToString(int mask)
{
    string result;
    result.reserve(26);
    for (int i = 0; i < 26; ++i)
    {
        if ((mask >> i) & 1)
        {
            result += static_cast<char>('a' + i);
        }
    }
    return result;
}$END$

